raw:
{
  "summary": [
    {
      "text": "Метод ПССС аппроксимирует нестационарный радиальный поток как последовательность стационарных состояний с растущим радиусом возмущения.",
      "claims": [
        "c1"
      ]
    },
    {
      "text": "Для постоянного дебита радиус зоны влияния растет по закону квадратного корня от времени.",
      "claims": [
        "c2"
      ]
    },
    {
      "text": "Метод дает погрешность около 5-10% в зависимости от времени и граничных условий.",
      "claims": [
        "c3"
      ]
    }
  ],
  "how_it_works": [
    {
      "text": "Рассматривается неограниченный горизонтальный пласт постоянной толщины h.",
      "claims": [
        "c4"
      ]
    },
    {
      "text": "В момент t=0 пущена скважина радиуса rc с постоянным дебитом Q.",
      "claims": [
        "c5"
      ]
    },
    {
      "text": "До пуска давление во всем пласте было одинаковым и равным pk.",
      "claims": [
        "c6"
      ]
    },
    {
      "text": "Через время t вокруг скважины образуется возмущенная область радиусом R(t).",
      "claims": [
        "c7"
      ]
    },
    {
      "text": "Внутри этой области давление распределено по стационарному закону.",
      "claims": [
        "c8"
      ]
    },
    {
      "text": "В остальной части пласта сохраняется начальное пластовое давление pk.",
      "claims": [
        "c9"
      ]
    },
    {
      "text": "Дебит описывается формулой, аналогичной формуле Дюпюи.",
      "claims": [
        "c10"
      ]
    },
    {
      "text": "Размеры возмущенной области находятся из уравнения материального баланса.",
      "claims": [
        "c11"
      ]
    },
    {
      "text": "Средневзвешенное пластовое давление определяется по формуле для установившегося потока.",
      "claims": [
        "c12"
      ]
    },
    {
      "text": "Подстановка выражений в уравнение баланса дает дифференциальное уравнение для R(t).",
      "claims": [
        "c13"
      ]
    },
    {
      "text": "Интегрирование приводит к закону движения границы R(t) = sqrt(rc^2 + 4*kappa*t).",
      "claims": [
        "c14"
      ]
    },
    {
      "text": "Давление в любой точке пласта в любой момент времени определяется подстановкой R(t) в стационарное уравнение.",
      "claims": [
        "c15"
      ]
    },
    {
      "text": "Депрессия на забое растет логарифмически с квадратным корнем из времени.",
      "claims": [
        "c16"
      ]
    },
    {
      "text": "Относительная погрешность метода уменьшается с течением времени.",
      "claims": [
        "c17"
      ]
    },
    {
      "text": "Для случая постоянного давления решение выражается медленно сходящимся рядом.",
      "claims": [
        "c18"
      ]
    },
    {
      "text": "В точке перехода от возмущенной к невозмущенной области градиент давления терпит разрыв.",
      "claims": [
        "c19"
      ]
    }
  ],
  "steps": [
    {
      "text": "Определяем параметры пласта: толщина h, проницаемость k, вязкость mu, радиус скважины rc.",
      "claims": [
        "c4"
      ]
    },
    {
      "text": "Задаем граничное условие: постоянный дебит Q или постоянное давление pc.",
      "claims": [
        "c5"
      ]
    },
    {
      "text": "Для постоянного дебита вычисляем радиус возмущения R(t) по формуле (24.14).",
      "claims": [
        "c14"
      ]
    },
    {
      "text": "Подставляем R(t) в формулу стационарного распределения давления (24.10).",
      "claims": [
        "c15"
      ]
    },
    {
      "text": "Вычисляем депрессию на забое по формуле (24.16).",
      "claims": [
        "c16"
      ]
    },
    {
      "text": "Для постоянного давления используем график (рис. 24.3) для определения R(t).",
      "claims": [
        "c18"
      ]
    }
  ],
  "examples": [
    {
      "title": "Оценка погрешности метода ПССС",
      "unit": "u499-08",
      "figure": null,
      "condition": [
        {
          "text": "Сравнение с точной формулой (23.52) для различных значений f0 = kappa*t/rc^2.",
          "claims": [
            "c17"
          ]
        }
      ],
      "solution": [
        {
          "text": "Вычисление относительной погрешности для f0 = 100, 10^3, 10^4.",
          "claims": [
            "c17"
          ]
        }
      ],
      "result": [
        {
          "text": "Погрешность составляет 10,6% при f0=100, 7,5% при f0=10^3, 5,7% при f0=10^4.",
          "claims": [
            "c17"
          ]
        }
      ]
    }
  ],
  "numbers": [
    {
      "text": "Погрешность 10,6% при f0 = 100.",
      "claims": [
        "c17"
      ]
    },
    {
      "text": "Погрешность 7,5% при f0 = 10^3.",
      "claims": [
        "c17"
      ]
    },
    {
      "text": "Погрешность 5,7% при f0 = 10^4.",
      "claims": [
        "c17"
      ]
    },
    {
      "text": "Погрешность определения дебита около 5% для случая постоянного давления.",
      "claims": [
        "c20"
      ]
    }
  ],
  "formulas": [
    {
      "unit": "u498-03",
      "latex": "p(r, t) = p_\\kappa - \\frac{Q\\mu}{2\\pi kh} \\ln \\frac{R(t)}{r}",
      "vars": [
        {
          "sym": "p(r, t)",
          "meaning": "давление в точке r в момент времени t",
          "unit": "Па"
        },
        {
          "sym": "p_\\kappa",
          "meaning": "контурное давление",
          "unit": "Па"
        },
        {
