          "meaning": "вязкость флюида",
          "unit": "Па·с"
        },
        {
          "sym": "k",
          "meaning": "проницаемость пласта",
          "unit": "м^2"
        },
        {
          "sym": "h",
          "meaning": "толщина пласта",
          "unit": "м"
        }]}]}
